css:
body {
	margin: 0;
	font-family: sans-serif;
}

.page.mk-1mbdoue {
				padding: 24px;
			}
			.title.mk-1mbdoue {
				font-size: 26px;
				font-weight: 700;
				color: #264653;
			}
			.open.mk-1mbdoue {
				display: block;
				margin-top: 16px;
				padding: 12px 20px;
				border: 2px solid #264653;
				border-radius: 12px;
				background: #ffffff;
				color: #264653;
				font-family: inherit;
				font-size: 18px;
			}
			.options.mk-1mbdoue {
				padding: 24px;
			}
			.toggle.mk-1mbdoue {
				display: block;
				width: 100%;
				padding: 14px 16px;
				border: 2px solid #264653;
				border-radius: 10px;
				background: #ffffff;
				color: #264653;
				font-family: inherit;
				font-size: 18px;
				text-align: left;
			}
			.toggle[ui-active].mk-1mbdoue {
				background: #2a9d8f;
				border-color: #2a9d8f;
				color: #ffffff;
			}
